tile = [[7,5,7,7,7,7,7],[7,7,7,7,5,7,5],[5,5,7,5,5,7,7],[7,5,5,5,5,7,5],[7,7,7,5,5,5,5],[5,7,5,5,7,5,7]]
out=[]
for r in range(13):
    if r == 6: out.append([6]*15)
    else:
        tr=tile[r%6]
        out.append(tr+[6]+tr)
assert len(out)==13 and all(len(r)==15 for r in out)
import json
print(json.dumps(out,separators=(',',':')))
